from pathlib import Path

p = Path('/home/ubuntu/zadak-ai-clone/client/src/pages/Home.tsx')
s = p.read_text()

s = s.replace('chartRange: string; noChartData: string;', 'chartRange: string; chartRange7: string; chartRange14: string; chartRange30: string; chartCaloriesAverage: string; chartLatestWeight: string; chartVisible: string; noChartData: string;', 1)
s = s.replace('chartRange: "آخر 14 يوماً", noChartData:', 'chartRange: "آخر 14 يوماً", chartRange7: "7 أيام", chartRange14: "14 يوماً", chartRange30: "30 يوماً", chartCaloriesAverage: "متوسط السعرات", chartLatestWeight: "آخر وزن", chartVisible: "عرض السلاسل", noChartData:', 1)
s = s.replace('chartRange: "Last 14 days", noChartData:', 'chartRange: "Last 14 days", chartRange7: "7 days", chartRange14: "14 days", chartRange30: "30 days", chartCaloriesAverage: "Average calories", chartLatestWeight: "Latest weight", chartVisible: "Visible series", noChartData:', 1)
s = s.replace('chartRange: "Son 14 gün", noChartData:', 'chartRange: "Son 14 gün", chartRange7: "7 gün", chartRange14: "14 gün", chartRange30: "30 gün", chartCaloriesAverage: "Ortalama kalori", chartLatestWeight: "Son kilo", chartVisible: "Görünen seriler", noChartData:', 1)

start = s.index('function StatsView(')
end = s.index('\nfunction StatCard(', start)
new_stats = r'''function StatsView({ meals, weightLogs, profile, t, language, dark, weeklyAverage }: { meals: Array<{ calories: number; protein: number; carbs: number; fat: number; createdAt: Date }>; weightLogs: Array<{ weightKg: number; loggedAt: Date }>; profile: { calorieGoal: number; proteinGoal: number }; t: Labels; language: Language; dark: boolean; weeklyAverage: number }) {
  const [chartDays, setChartDays] = useState<7 | 14 | 30>(14);
  const [visibleSeries, setVisibleSeries] = useState({ calories: true, weight: true });
  const recent = meals.filter((meal) => new Date(meal.createdAt).getTime() >= Date.now() - 7 * 86_400_000);
  const avgProtein = recent.length ? Math.round(recent.reduce((sum, meal) => sum + meal.protein, 0) / recent.length) : 0;
  const maxCalories = Math.max(profile.calorieGoal, ...Array.from({ length: 7 }, (_, index) => recent.filter((meal) => new Date(meal.createdAt).getDay() === (new Date().getDay() - index + 7) % 7).reduce((sum, meal) => sum + meal.calories, 0)));
  const chartData = useMemo(() => buildNutritionComparison(meals, weightLogs, chartDays, new Date(), language === "ar" ? "ar-EG" : language), [meals, weightLogs, chartDays, language]);
  const hasCalories = chartData.some((day) => day.calories > 0);
  const hasWeight = chartData.some((day) => day.weight != null);
  const hasComparisonData = hasCalories || hasWeight;
  const averageChartCalories = hasCalories ? Math.round(chartData.reduce((sum, day) => sum + day.calories, 0) / chartData.length) : 0;
  const latestWeight = [...chartData].reverse().find((day) => day.weight != null)?.weight;
  const rangeLabel = chartDays === 7 ? t.chartRange7 : chartDays === 30 ? t.chartRange30 : t.chartRange14;
  const rangeButton = (days: 7 | 14 | 30, label: string) => <button type="button" onClick={() => setChartDays(days)} className={`rounded-full px-3 py-1.5 text-[10px] font-bold transition-all active:scale-95 ${chartDays === days ? "bg-[#087b69] text-white shadow-sm" : dark ? "text-[#afc5b6] hover:bg-white/10" : "text-[#718477] hover:bg-[#eef7ef]"}`} aria-pressed={chartDays === days}>{label}</button>;
  const seriesButton = (key: "calories" | "weight", label: string, color: string) => <button type="button" onClick={() => setVisibleSeries((current) => ({ ...current, [key]: !current[key] }))} className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1.5 text-[10px] font-bold transition-all active:scale-95 ${visibleSeries[key] ? dark ? "border-white/10 bg-white/10 text-[#d9e8dc]" : "border-[#d9e8dc] bg-[#f7fbf6] text-[#526158]" : dark ? "border-white/5 text-[#6f8a79] opacity-60" : "border-[#edf2ed] text-[#9aa69d] opacity-70"}`} aria-pressed={visibleSeries[key]}><span className="h-2 w-2 rounded-full" style={{ backgroundColor: color }} />{label}</button>;
  return <main className="mx-auto max-w-[1180px] px-5 pb-10 pt-8 lg:px-8"><div className="mb-6"><div className="mb-2 text-xs font-semibold text-[#8a988e]">{t.stats}</div><h1 className="text-3xl font-black">{t.statsTitle}</h1></div><div className="grid gap-4 sm:grid-cols-3"><StatCard label={t.totalMeals} value={String(recent.length)} icon={<Utensils size={18} />} dark={dark} /><StatCard label={t.avgCalories} value={formatNumber(weeklyAverage, language)} icon={<Zap size={18} />} dark={dark} /><StatCard label={t.avgProtein} value={`${avgProtein}غ`} icon={<Activity size={18} />} dark={dark} /></div><section className={`mt-5 rounded-[24px] p-6 shadow-sm ${dark ? "bg-[#20312b]" : "bg-white"}`}><div className="mb-5 flex items-center justify-between"><h2 className="font-black">{t.weekly}</h2><span className="text-xs text-[#8a978e]">{profile.calorieGoal} {t.calories}</span></div><div className="flex h-52 items-end justify-between gap-2">{Array.from({ length: 7 }, (_, index) => { const day = (new Date().getDay() - 6 + index + 7) % 7; const total = recent.filter((meal) => new Date(meal.createdAt).getDay() === day).reduce((sum, meal) => sum + meal.calories, 0); const height = maxCalories ? Math.max(8, (total / maxCalories) * 100) : 8; return <div key={index} className="flex h-full flex-1 flex-col items-center justify-end gap-2"><div className="w-full max-w-12 rounded-t-xl bg-gradient-to-t from-[#087b69] to-[#79c39a] transition-all" style={{ height: `${height}%` }} /><span className="text-[10px] text-[#8b978f]">{new Date(Date.now() - (6 - index) * 86_400_000).toLocaleDateString(language === "ar" ? "ar-EG" : language, { weekday: "short" })}</span></div>; })}</div></section><section className={`mt-5 rounded-[24px] p-5 shadow-sm sm:p-6 ${dark ? "bg-[#20312b]" : "bg-white"}`}><div className="flex flex-col gap-4"><div className="flex flex-wrap items-start justify-between gap-3"><div className="flex items-center gap-2"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#eaf6eb] text-[#16866f]"><BarChart3 size={17} /></div><div><h2 className="font-black">{t.chartTitle}</h2><p className={`mt-1 max-w-[620px] text-[10px] leading-5 ${dark ? "text-[#a3b8aa]" : "text-[#849188]"}`}>{t.chartHint}</p></div></div><span className={`rounded-full px-3 py-1.5 text-[10px] font-bold ${dark ? "bg-white/10 text-[#b8d4c0]" : "bg-[#f4f8f1] text-[#718477]"}`}>{rangeLabel}</span></div><div className={`flex flex-wrap items-center justify-between gap-3 rounded-2xl p-2 ${dark ? "bg-[#182a23]" : "bg-[#f8fbf7]"}`}><div className="flex items-center gap-1" aria-label={t.chartRange}><span className="px-2 text-[10px] font-bold text-[#8a978f]">{t.chartRange}</span>{rangeButton(7, t.chartRange7)}{rangeButton(14, t.chartRange14)}{rangeButton(30, t.chartRange30)}</div><div className="flex items-center gap-1.5" aria-label={t.chartVisible}>{seriesButton("calories", t.caloriesSeries, "#16866f")}{seriesButton("weight", t.weightSeries, "#d49c3e")}</div></div>{hasComparisonData && <div className="grid grid-cols-2 gap-2 sm:grid-cols-3"><div className={`rounded-2xl p-3 ${dark ? "bg-[#182a23]" : "bg-[#f7faf6]"}`}><div className="text-[9px] text-[#8b978e]">{t.chartCaloriesAverage}</div><div className="mt-1 text-lg font-black text-[#16866f]">{formatNumber(averageChartCalories, language)}</div></div><div className={`rounded-2xl p-3 ${dark ? "bg-[#182a23]" : "bg-[#f7faf6]"}`}><div className="text-[9px] text-[#8b978e]">{t.chartLatestWeight}</div><div className="mt-1 text-lg font-black text-[#d49c3e]">{latestWeight != null ? `${formatNumber(latestWeight, language)} كغ` : "—"}</div></div><div className={`col-span-2 rounded-2xl p-3 sm:col-span-1 ${dark ? "bg-[#182a23]" : "bg-[#f7faf6]"}`}><div className="text-[9px] text-[#8b978e]">{t.chartRange}</div><div className="mt-1 text-lg font-black">{chartDays} <span className="text-[10px] font-medium text-[#8b978e]">{language === "ar" ? "يوماً" : language === "tr" ? "gün" : "days"}</span></div></div></div>}{hasComparisonData ? <div className="mt-1" dir="ltr"><div className="h-[320px] w-full"><ResponsiveContainer width="100%" height="100%"><LineChart data={chartData} margin={{ top: 8, right: 8, left: -16, bottom: 4 }}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke={dark ? "#365246" : "#e5eee5"} /><XAxis dataKey="label" tick={{ fill: dark ? "#9fb8a8" : "#829188", fontSize: 10 }} tickLine={false} axisLine={false} /><YAxis yAxisId="calories" tick={{ fill: dark ? "#9fb8a8" : "#829188", fontSize: 10 }} tickLine={false} axisLine={false} width={42} /><YAxis yAxisId="weight" orientation="right" tick={{ fill: dark ? "#d2b477" : "#a98a4b", fontSize: 10 }} tickLine={false} axisLine={false} width={35} domain={["dataMin - 2", "dataMax + 2"]} /><Tooltip contentStyle={{ borderRadius: 14, border: dark ? "1px solid #385449" : "1px solid #e0e9df", backgroundColor: dark ? "#20312b" : "#ffffff", fontSize: 11, direction: language === "ar" ? "rtl" : "ltr" }} labelStyle={{ color: dark ? "#d7e7dc" : "#455148", fontWeight: 700 }} /><Legend wrapperStyle={{ fontSize: 10, paddingTop: 8 }} />{visibleSeries.calories && <Line yAxisId="calories" type="monotone" dataKey="calories" name={t.caloriesSeries} stroke="#16866f" strokeWidth={3} dot={{ r: 3, fill: "#16866f" }} activeDot={{ r: 6 }} connectNulls />}{visibleSeries.weight && <Line yAxisId="weight" type="monotone" dataKey="weight" name={t.weightSeries} stroke="#d49c3e" strokeWidth={2.5} strokeDasharray="5 4" dot={{ r: 3, fill: "#d49c3e" }} activeDot={{ r: 6 }} connectNulls />}</LineChart></ResponsiveContainer></div></div> : <div className={`mt-1 grid min-h-[230px] place-items-center rounded-2xl border border-dashed px-6 text-center ${dark ? "border-white/10 bg-[#182a23]" : "border-[#dfeadf] bg-[#fbfdf9]"}`}><div><BarChart3 className="mx-auto mb-3 text-[#8fc5a8]" size={30} /><p className="text-sm font-bold">{t.noChartData}</p><p className="mt-1 text-[10px] text-[#849188]">{t.chartHint}</p></div></div>}</div></section></main>;
}'''
s = s[:start] + new_stats + s[end:]
p.write_text(s)
print('charts-enhanced')
